// Saves an expense through the API and resolves with the new id.
// - Rejects with "Description is required" if the description is blank.
// - Rejects with "Amount must be positive" unless amountCents is a
//   positive integer. Invalid input never reaches the API.
// - If api.post fails with an error that has { retryable: true },
//   it tries exactly ONE more time.
// - Any other API error is passed on: the promise rejects with it.
async function saveExpense(expense, api) {
  if (!expense.description || !expense.description.trim()) {
    throw new Error('Description is required');
  }
  if (!Number.isInteger(expense.amountCents) || expense.amountCents <= 0) {
    throw new Error('Amount must be positive');
  }
  try {
    const { id } = await api.post('/expenses', expense);
    return id;
  } catch (error) {
    if (!error.retryable) throw error;
    const { id } = await api.post('/expenses', expense);
    return id;
  }
}

