const dinner = { description: 'Dinner', amountCents: 4500 };

function stubApi(...steps) {
  const api = {
    calls: 0,
    async post() {
      const step = steps[api.calls];
      api.calls += 1;
      if (step instanceof Error) throw step;
      return step;
    },
  };
  return api;
}

const retryable = (message) => Object.assign(new Error(message), { retryable: true });

describe('saveExpense', () => {
  test('rejects a blank description without calling the API', async () => {
    const api = stubApi({ id: 'e1' });

    await expect(saveExpense({ description: ' ', amountCents: 100 }, api)).rejects.toThrow('Description is required');
    expect(api.calls).toBe(0);
  });

  test('resolves with the id from the API', async () => {
    const api = stubApi({ id: 'e1' });

    await expect(saveExpense(dinner, api)).resolves.toBe('e1');
    expect(api.calls).toBe(1);
  });

  test('retries once after a retryable error', async () => {
    const api = stubApi(retryable('Timed out'), { id: 'e2' });

    await expect(saveExpense(dinner, api)).resolves.toBe('e2');
    expect(api.calls).toBe(2);
  });

  test('passes on a non-retryable error without retrying', async () => {
    const api = stubApi(new Error('Amount too large'), { id: 'e3' });

    await expect(saveExpense(dinner, api)).rejects.toThrow('Amount too large');
    expect(api.calls).toBe(1);
  });
});
